def pick(xs: list[int], seed: int) -> int:
    """Return an element of the non-empty list xs, chosen deterministically from seed.

    The same (xs, seed) pair always yields the same element. No randomness is used.
    """
    if not xs:
        raise ValueError("pick() requires a non-empty list")
    mask = 0xFFFFFFFFFFFFFFFF
    z = (seed + 0x9E3779B97F4A7C15) & mask
    z = ((z ^ (z >> 30)) * 0xBF58476D1CE4E5B9) & mask
    z = ((z ^ (z >> 27)) * 0x94D049BB133111EB) & mask
    z ^= z >> 31
    return xs[z % len(xs)]


def test_pick_returns_member() -> None:
    xs = [4, 8, 15, 16, 23, 42]
    for seed in range(50):
        assert pick(xs, seed) in xs


def test_pick_same_seed_same_result() -> None:
    xs = [4, 8, 15, 16, 23, 42]
    for seed in range(50):
        assert pick(xs, seed) == pick(xs, seed)


def test_pick_is_stable_across_equal_lists() -> None:
    xs = [1, 2, 3, 5, 8, 13]
    ys = list(xs)
    for seed in range(50):
        assert pick(xs, seed) == pick(ys, seed)


def test_pick_singleton() -> None:
    for seed in range(20):
        assert pick([7], seed) == 7


def test_pick_negative_seed_is_accepted() -> None:
    xs = [10, 20, 30]
    assert pick(xs, -1) in xs
    assert pick(xs, -1) == pick(xs, -1)
